<?php
namespace Yablonsky\PerformanceSEO\SEO\Sitemap;

if ( ! defined( 'ABSPATH' ) ) { exit; }

/**
 * Keeps external/page-cache copies of YSEO sitemap endpoints coherent.
 *
 * The sitemap bodies are still generated by YSEO as classic XML. This adapter
 * only invalidates stale cached HTTP responses through cache-provider APIs when
 * those APIs are already present. It never rewrites another plugin's settings.
 */
final class SitemapPageCacheCompatibility {
    private const OPTION_VERSION = 'yseo_sitemap_page_cache_compat_version';

    /** @var SitemapRepository */
    private $repository;
    /** @var array<string,bool> */
    private $flushed = array();
    /** @var array<string,string> */
    private $pendingPerformanceUrls = array();
    /** @var bool */
    private $performanceFlushHookRegistered = false;
    /** @var bool */
    private $pendingPerformanceFullPurge = false;

    public function __construct( SitemapRepository $repository ) {
        $this->repository = $repository;
    }

    public function register(): void {
        add_action( 'yablonsky_seo_sitemap_bucket_invalidated_v1', array( $this, 'flushBucket' ), 10, 3 );
        add_action( 'yablonsky_seo_sitemap_index_invalidated_v1', array( $this, 'flushIndex' ) );
        add_action( 'yablonsky_seo_sitemap_full_invalidate_v1', array( $this, 'flushAllKnown' ) );
    }

    public function maybeFlushForUpgrade(): void {
        $previousVersion = (string) get_option( self::OPTION_VERSION, '' );
        if ( YPS_VERSION === $previousVersion ) { return; }

        $this->flushAllKnown();

        // 5.55.2 is the atomic response boundary for sitemap responses that
        // could remain cached upstream with an old text/html MIME. Exact URL
        // purges remain the normal policy. On an upgrade from an older installed
        // YSEO version, allow W3 Total Cache one bounded full-provider purge so
        // an edge copy that ignored URL-level invalidation cannot survive the
        // transport correction. Fresh installs never take this path.
        if ( '' !== $previousVersion && version_compare( $previousVersion, '5.55.2', '<' ) ) {
            $this->recoverLegacyTransportCache();
        }

        update_option( self::OPTION_VERSION, YPS_VERSION, false );
    }

    public function flushIndex(): void {
        $urls = array();
        foreach ( array( '/sitemap_index.xml', '/sitemap.xml', '/wp-sitemap.xml' ) as $path ) {
            $url = home_url( $path );
            $this->flushUrl( $url );
            $urls[] = $url;
        }
        $this->signalPerformanceInvalidation( $urls, 'yseo_sitemap_index' );
    }

    public function flushBucket( string $type, string $subtype, int $bucket ): void {
        $slug = $this->slugFor( sanitize_key( $type ), sanitize_key( $subtype ), $this->repository->manifest() );
        if ( '' === $slug ) { return; }
        $bucket = max( 1, $bucket );
        $url = home_url( '/' . $slug . '-sitemap' . ( $bucket > 1 ? $bucket : '' ) . '.xml' );
        $this->flushUrl( $url );
        $this->signalPerformanceInvalidation( array( $url ), 'yseo_sitemap_bucket' );
    }

    public function flushAllKnown(): void {
        $urls = array();
        foreach ( array( '/sitemap_index.xml', '/sitemap.xml', '/wp-sitemap.xml' ) as $path ) {
            $urls[] = home_url( $path );
        }
        $manifest = $this->repository->manifest();
        foreach ( $manifest as $row ) {
            if ( ! is_array( $row ) ) { continue; }
            $type = sanitize_key( (string) ( $row['resource_type'] ?? '' ) );
            $subtype = sanitize_key( (string) ( $row['resource_subtype'] ?? '' ) );
            $bucket = max( 1, (int) ( $row['bucket_no'] ?? 1 ) );
            $slug = $this->slugFor( $type, $subtype, $manifest );
            if ( '' === $slug ) { continue; }
            $urls[] = home_url( '/' . $slug . '-sitemap' . ( $bucket > 1 ? $bucket : '' ) . '.xml' );
        }
        foreach ( array( '/news-sitemap.xml', '/video-sitemap.xml', '/geo-sitemap.xml', '/schemamap.xml' ) as $path ) {
            $urls[] = home_url( $path );
        }
        $urls = array_values( array_unique( $urls ) );
        foreach ( $urls as $url ) { $this->flushUrl( $url ); }
        $this->signalPerformanceInvalidation( $urls, 'yseo_sitemap_full' );
    }

    /** @param array<int,array<string,mixed>> $manifest */
    private function slugFor( string $type, string $subtype, array $manifest ): string {
        $resources = array();
        foreach ( $manifest as $row ) {
            if ( ! is_array( $row ) ) { continue; }
            $rowType = sanitize_key( (string) ( $row['resource_type'] ?? '' ) );
            $rowSubtype = sanitize_key( (string) ( $row['resource_subtype'] ?? '' ) );
            $key = $rowType . ':' . $rowSubtype;
            if ( isset( $resources[ $key ] ) ) { continue; }
            $base = 'author' === $rowType ? 'author' : $rowSubtype;
            if ( '' === $base ) { continue; }
            $resources[ $key ] = array( 'type' => $rowType, 'subtype' => $rowSubtype, 'base' => $base );
        }

        $baseCounts = array();
        foreach ( $resources as $resource ) {
            $base = (string) $resource['base'];
            $baseCounts[ $base ] = isset( $baseCounts[ $base ] ) ? $baseCounts[ $base ] + 1 : 1;
        }

        $bySlug = array();
        $wanted = '';
        foreach ( $resources as $key => $resource ) {
            $base = (string) $resource['base'];
            $rowType = (string) $resource['type'];
            $rowSubtype = (string) $resource['subtype'];
            if ( 1 === (int) $baseCounts[ $base ] ) {
                $slug = $base;
            } else {
                $slug = 'post' === $rowType ? 'post-' . $base : ( 'term' === $rowType ? 'term-' . $base : 'author-archive' );
            }
            if ( isset( $bySlug[ $slug ] ) ) { $slug .= '-' . substr( hash( 'sha256', $key ), 0, 8 ); }
            $bySlug[ $slug ] = true;
            if ( $rowType === $type && $rowSubtype === $subtype ) { $wanted = $slug; }
        }
        return $wanted;
    }

    /**
     * Emits the shared Yablonsky cache-invalidation intent without taking cache
     * execution authority away from Yablonsky Performance. Extra arguments are
     * backward-safe for listeners that only accept the URL list.
     *
     * @param array<int,string> $urls
     */
    private function signalPerformanceInvalidation( array $urls, string $context ): void {
        $clean = array();
        foreach ( $urls as $url ) {
            $url = esc_url_raw( (string) $url, array( 'http', 'https' ) );
            if ( '' !== $url ) { $clean[ $url ] = $url; }
        }
        if ( empty( $clean ) ) { return; }
        if ( did_action( 'init' ) > 0 ) {
            do_action( 'yablonsky_performance_invalidate_urls', array_values( $clean ), sanitize_key( $context ) );
            return;
        }
        foreach ( $clean as $url ) { $this->pendingPerformanceUrls[ $url ] = $url; }
        if ( ! $this->performanceFlushHookRegistered ) {
            $this->performanceFlushHookRegistered = true;
            add_action( 'init', array( $this, 'flushPendingPerformanceInvalidation' ), PHP_INT_MAX );
        }
    }

    public function flushPendingPerformanceInvalidation(): void {
        if ( empty( $this->pendingPerformanceUrls ) ) { return; }
        $urls = array_values( $this->pendingPerformanceUrls );
        $this->pendingPerformanceUrls = array();
        do_action( 'yablonsky_performance_invalidate_urls', $urls, 'yseo_sitemap_deferred' );
    }


    private function recoverLegacyTransportCache(): void {
        if ( function_exists( 'w3tc_flush_all' ) ) {
            try { w3tc_flush_all(); } catch ( \Throwable $error ) { unset( $error ); }
        }

        // YPerf's portable page cache executes from advanced-cache.php before
        // normal plugins. Exact URL invalidation remains the steady-state rule,
        // but a transport-boundary upgrade must also evict any historical HTML
        // response that could otherwise short-circuit WordPress before YSEO can
        // establish application/xml. YPerf remains the executor of this purge.
        if ( did_action( 'init' ) > 0 ) {
            do_action( 'yablonsky_performance_invalidate_all', 'yseo_sitemap_transport_5552' );
        } else {
            $this->pendingPerformanceFullPurge = true;
            add_action( 'init', array( $this, 'flushPendingPerformanceFullInvalidation' ), PHP_INT_MAX );
        }
        do_action( 'yablonsky_seo_sitemap_transport_recovery_v1' );
    }

    public function flushPendingPerformanceFullInvalidation(): void {
        if ( ! $this->pendingPerformanceFullPurge ) { return; }
        $this->pendingPerformanceFullPurge = false;
        do_action( 'yablonsky_performance_invalidate_all', 'yseo_sitemap_transport_5552' );
    }

    private function flushUrl( string $url ): void {
        $url = esc_url_raw( $url, array( 'http', 'https' ) );
        if ( '' === $url || isset( $this->flushed[ $url ] ) ) { return; }
        $this->flushed[ $url ] = true;
        if ( function_exists( 'w3tc_flush_url' ) ) {
            try { w3tc_flush_url( $url ); } catch ( \Throwable $error ) { unset( $error ); }
        }
        do_action( 'yablonsky_seo_sitemap_cache_flush_url_v1', $url );
    }
}
